-- Actual KubeCon NA 2026 programming through Thursday, November 12.
-- Snapshot: 2026-11-09, https://sessionize.com/api/v2/svi82w6c/view/All
-- Published page: https://events.linuxfoundation.org/kubecon-cloudnativecon-north-america/program/schedule/
-- 494 eligible Tue/ Wed/ Thu source entries: 185 / 195 / 114.
-- 52 Tuesday entries already exist under their original (sometimes shortened) titles.
-- Excludes registration, bag check, breaks, general expo/poster/kiosk opening hours.
-- Local America/Denver times. PostgreSQL 24:00 represents the next midnight.
-- Only factual session metadata is copied; descriptions are available via Source links.

-- Records ownership and prior values for a safe, data-preserving down migration.
CREATE TABLE schedule_009_changes (
    kind text NOT NULL,
    id integer NOT NULL,
    related_id integer NOT NULL DEFAULT 0,
    old_hidden boolean,
    PRIMARY KEY (kind, id, related_id)
);

-- Match specific logistics titles, not the seed's unreliable format field:
-- session 62 is a real talk accidentally labeled Break.
INSERT INTO schedule_009_changes (kind,id,old_hidden)
SELECT 'hidden',id,hidden FROM sessions
WHERE title IN ('Registration + Badge Pick-Up','Coat + Bag Check','☕ Coffee Break','Solutions Showcase')
   OR title LIKE '🍲 Lunch%'
   OR title LIKE 'Project Pavilion Kiosks |%'
   OR title LIKE 'Poster Showcase (self-guided%'
   OR title = 'Explore the Poster Showcase';
UPDATE sessions SET hidden=true WHERE id IN (SELECT id FROM schedule_009_changes WHERE kind='hidden');

-- New geometry traced from official venue drawings, in the existing approximate
-- geographic coordinate convention. Foyer/mezzanine are area pins, not boundaries.
-- Hyatt: https://assets.hyatt.com/content/dam/hyatt/hyattdam/documents/2021/03/17/1234/Hyatt-Regency-Salt-Lake-City-Floor-Plan-English.pdf
-- Salt Palace: https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/saltlake/SPCC_Brochure_2021_f18cc627-99e8-4ecd-87ed-d65c4aebdcae.pdf
WITH inserted AS (
    INSERT INTO rooms (venue,floor,name,boundary)
    SELECT venue,floor,name,boundary FROM jsonb_to_recordset($rooms$
[
{"venue":"Hyatt Regency","floor":3,"name":"Park City","boundary":{"type":"Polygon","coordinates":[[[-111.894450556115,40.765275575367],[-111.894222538849,40.765275575367],[-111.894228055396,40.765250260848],[-111.894242766187,40.76522494633],[-111.89427218777,40.765205257259],[-111.894303448201,40.765195412724],[-111.894334708633,40.765191193638],[-111.894375163309,40.765195412724],[-111.894406423741,40.765205257259],[-111.894432167626,40.765223539967],[-111.894445039568,40.765246041762],[-111.894450556115,40.765275575367]]]}},
{"venue":"Salt Palace","floor":1,"name":"North Grand Ballroom Foyer","boundary":{"type":"Point","coordinates":[-111.894923838307,40.76699616961]}},
{"venue":"Salt Palace","floor":2,"name":"Upper Mezzanine","boundary":{"type":"Point","coordinates":[-111.897005196882,40.768397760441]}}
]
$rooms$::jsonb) AS r(venue text,floor integer,name text,boundary jsonb)
    ON CONFLICT (venue,floor,name) DO NOTHING RETURNING id
) INSERT INTO schedule_009_changes(kind,id) SELECT 'room',id FROM inserted;

