$events$::jsonb) AS s(source_id text,date date,start_time time,end_time time,title text,
    existing_title text,track text,level text,format text,venue text,floor text,room text,speakers jsonb,notes text);

DO $import$
DECLARE
    event record;
    day_key integer;
    track_key integer;
    location_key integer;
    session_key integer;
    speaker_key integer;
    speaker_name text;
BEGIN
    FOR event IN SELECT * FROM schedule_009_source ORDER BY date,start_time,source_id LOOP
        -- Do not modify existing session metadata or explicit event-room overrides.
        -- Also recognizes rows retained after rollback because they have user activity.
        SELECT s.id INTO session_key FROM sessions s
        JOIN days d ON d.id=s.day_id JOIN locations l ON l.id=s.location_id
        WHERE d.event_date=event.date AND s.start_time=event.start_time
          AND s.title IN (event.title,event.existing_title)
          AND l.venue=event.venue AND l.level IS NOT DISTINCT FROM event.floor
          AND l.room IS NOT DISTINCT FROM event.room
        ORDER BY s.id LIMIT 1;
        IF session_key IS NOT NULL THEN CONTINUE; END IF;

        INSERT INTO days(event_date,label)
        VALUES(event.date,to_char(event.date,'Dy Mon FMDD'))
        ON CONFLICT(event_date) DO NOTHING RETURNING id INTO day_key;
        IF day_key IS NULL THEN SELECT id INTO day_key FROM days WHERE event_date=event.date;
        ELSE INSERT INTO schedule_009_changes(kind,id) VALUES('day',day_key); END IF;

        INSERT INTO tracks(name) VALUES(event.track)
        ON CONFLICT(name) DO NOTHING RETURNING id INTO track_key;
        IF track_key IS NULL THEN SELECT id INTO track_key FROM tracks WHERE name=event.track;
        ELSE INSERT INTO schedule_009_changes(kind,id) VALUES('track',track_key); END IF;

        INSERT INTO locations(venue,level,room) VALUES(event.venue,event.floor,event.room)
        ON CONFLICT DO NOTHING RETURNING id INTO location_key;
        IF location_key IS NULL THEN
            SELECT id INTO location_key FROM locations WHERE venue=event.venue
              AND level IS NOT DISTINCT FROM event.floor AND room IS NOT DISTINCT FROM event.room;
        ELSE INSERT INTO schedule_009_changes(kind,id) VALUES('location',location_key); END IF;

        INSERT INTO sessions(day_id,start_time,end_time,title,track_id,level,format,location_id,notes)
        VALUES(day_key,event.start_time,event.end_time,event.title,track_key,event.level,event.format,location_key,event.notes)
        RETURNING id INTO session_key;
        INSERT INTO schedule_009_changes(kind,id) VALUES('session',session_key);

        FOR speaker_name IN SELECT jsonb_array_elements_text(event.speakers) LOOP
            INSERT INTO speakers(name) VALUES(speaker_name)
            ON CONFLICT(name) DO NOTHING RETURNING id INTO speaker_key;
            IF speaker_key IS NULL THEN SELECT id INTO speaker_key FROM speakers WHERE name=speaker_name;
            ELSE INSERT INTO schedule_009_changes(kind,id) VALUES('speaker',speaker_key); END IF;
            INSERT INTO session_speakers(session_id,speaker_id) VALUES(session_key,speaker_key) ON CONFLICT DO NOTHING;
        END LOOP;
    END LOOP;
END
$import$;

-- Exact source-label aliases resolve to existing room groups. Broad expo labels
-- intentionally highlight all published halls, never an invented booth location.
WITH mapping AS (
    SELECT * FROM jsonb_to_recordset($mapping$
[
