$mapping$::jsonb) AS m(venue text,floor text,room text,names jsonb)
), inserted AS (
    INSERT INTO location_rooms(location_id,room_id)
    SELECT l.id,r.id FROM mapping m JOIN locations l
      ON l.venue=m.venue AND l.level=m.floor AND l.room=m.room
    JOIN rooms r ON r.venue=m.venue AND 'Level '||r.floor=m.floor
      AND m.names ? r.name
    ON CONFLICT DO NOTHING RETURNING location_id,room_id
) INSERT INTO schedule_009_changes(kind,id,related_id) SELECT 'location_room',location_id,room_id FROM inserted;

INSERT INTO session_rooms(session_id,room_id)
SELECT s.id,lr.room_id FROM sessions s JOIN location_rooms lr ON lr.location_id=s.location_id
JOIN schedule_009_changes c ON c.kind='session' AND c.id=s.id;

-- Fail atomically if source changes or a missing alias would silently lose data.
DO $verify$
BEGIN
    IF EXISTS (
        SELECT 1 FROM schedule_009_source e WHERE NOT EXISTS (
            SELECT 1 FROM sessions s JOIN days d ON d.id=s.day_id JOIN locations l ON l.id=s.location_id
            WHERE d.event_date=e.date AND s.start_time=e.start_time
              AND s.title IN(e.title,e.existing_title) AND l.venue=e.venue
              AND l.level IS NOT DISTINCT FROM e.floor AND l.room IS NOT DISTINCT FROM e.room
        )
    ) THEN RAISE EXCEPTION 'Schedule snapshot has unresolved sessions'; END IF;
    IF EXISTS (
        SELECT 1 FROM sessions s JOIN schedule_009_changes c ON c.kind='session' AND c.id=s.id
        JOIN locations l ON l.id=s.location_id
        WHERE l.venue IN('Salt Palace','Hyatt Regency')
          AND NOT EXISTS(SELECT 1 FROM session_rooms sr WHERE sr.session_id=s.id)
    ) THEN RAISE EXCEPTION 'Imported indoor event has no room mapping'; END IF;
END
$verify$;
